import { unstable_cache } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
};

// In-memory store for demo (resets on server restart)
const postsStore: Post[] = [
  {
    id: '1',
    title: 'Welcome',
    content: 'This is the first post.',
    createdAt: new Date(),
  },
];

export async function getPosts(): Promise<Post[]> {
  return unstable_cache(
    async () => {
      return [...postsStore].sort(
        (a, b) => b.createdAt.getTime() - a.createdAt.getTime()
      );
    },
    ['posts-list'],
    { tags: ['posts'] }
  )();
}

export function addPost(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date(),
  };
  postsStore.push(post);
  return post;
}

