'use server';

import { updateTag } from 'next/cache';
import { addPost } from '@/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title?.trim() || !content?.trim()) {
    return { error: 'Title and content are required' };
  }

  addPost(title.trim(), content.trim());

  // Invalidate the "posts" cache tag so the next page load fetches fresh data.
  // updateTag guarantees no stale content is served - the next request will
  // wait for fresh data rather than serving old cached content.
  updateTag('posts');

  return { success: true };
}

